var a=`0845-bhindi-masala`;var n=`world-0845`;var t=`IN`;var o=`south-asia`;var s=4;var r=30;var g={en:`Bhindi Masala`,ua:`Бхінді масала`};var d={en:`Bhindi Masala is a India dish made with yellow onion, tomato, ginger-garlic paste, okra. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Бхінді масала, страва кухні країни Індія. Основні складники: жовта цибуля, помідор, імбирно-часникова паста, бамія. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`tomato`,290,`g`],[`canola-oil`,45,`ml`],[`ginger-garlic-paste`,20,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 17 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 17 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:17,i:[[`okra`,610,`g`],[`ground-cumin`,6,`g`],[`ground-turmeric`,3,`g`],[`ground-coriander`,6,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`amchur-powder`,4,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:a,id:n,country:`IN`,region:o,servings:4,minutes:30,title:g,text:d,steps:l};export{t as country,u as default,n as id,r as minutes,o as region,s as servings,a as slug,l as steps,d as text,g as title};